import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { FaStar, FaChevronLeft, FaMapMarkerAlt, FaCalendarAlt, FaUsers } from 'react-icons/fa';
import './TourDetail.css';


const TourDetails = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [tour, setTour] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchTour = async () => {
      try {
        setLoading(true);
        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5000';
        const response = await axios.get(`${apiUrl}/api/tours/${id}`);

        let tourData = null;
        // Handle various possible response shapes
        if (response.data && Array.isArray(response.data)) {
          tourData = response.data.find(t => (t._id || t.id) === id);
        } else if (response.data && response.data.data) {
          // data might be array or object
          if (Array.isArray(response.data.data)) {
            tourData = response.data.data.find(t => (t._id || t.id) === id);
          } else {
            tourData = response.data.data;
          }
        } else if (response.data) {
          tourData = response.data;
        }

        if (!tourData) {
          throw new Error('Tour not found');
        }
        setTour(tourData);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching tour:', err);
        setError('Failed to load tour details');
        setLoading(false);
      }
    };

    fetchTour();
  }, [id]);

  if (loading) {
    return <div className="loading">Loading tour details…</div>;
  }

  if (error) {
    return (
      <div className="error-message">
        <p>{error}</p>
        <button className="btn btn-primary" onClick={() => navigate(-1)}>
          <FaChevronLeft /> Go Back
        </button>
      </div>
    );
  }

  if (!tour) {
    return <div className="not-found">Tour not found</div>;
  }

  const imageUrl = tour.coverImage || tour.imageCover || (Array.isArray(tour.images) ? tour.images[0] : null);
  const destination = tour.destination?.name || tour.destination?.country || tour.country || '';
  const price = tour.price || tour.pricePerPerson || tour.priceUSD || null;
  const duration = tour.duration || (tour.days ? `${tour.days} days` : null);

  return (
    <section className="tour-details-page">
      <div className="container">
        <button className="back-btn" onClick={() => navigate(-1)}>
          <FaChevronLeft /> Back
        </button>

        <div className="tour-header">
          {imageUrl && (
            <div className="tour-hero">
              <img src={imageUrl} alt={tour.title || tour.name} />
            </div>
          )}
          <h1 className="tour-title">{tour.title || tour.name}</h1>
          <div className="tour-meta">
            {destination && (
              <span className="meta-item"><FaMapMarkerAlt /> {destination}</span>
            )}
            {duration && (
              <span className="meta-item"><FaCalendarAlt /> {duration}</span>
            )}
            {tour.groupSize && (
              <span className="meta-item"><FaUsers /> Up to {tour.groupSize}</span>
            )}
            {price && (
              <span className="meta-item price">${price}</span>
            )}
          </div>
        </div>

        {tour.description && (
          <div className="tour-description">
            <h2>Overview</h2>
            <p>{tour.description}</p>
          </div>
        )}

        <div className="tour-rating">
          {[1,2,3,4,5].map(i => (
            <FaStar key={i} style={{color: i <= Math.round(tour.ratingsAverage || 4.5) ? '#f39c12' : '#ccc'}} />
          ))}
          <span className="rating-count">({tour.ratingsQuantity || 0} reviews)</span>
        </div>

        <Link to={`/book/${tour._id || tour.id}`} className="btn btn-primary book-btn">
          Book Now
        </Link>
      </div>
    </section>
  );
};

export default TourDetails;